"""Factual product explanation; operator identity must be supplied, not invented."""
from html import escape
from urllib.parse import quote
from account_mail import normalize_email


def render_data_notice(operator='', contact=''):
    try:
        contact = normalize_email(contact) if contact else ''
    except ValueError:
        contact = ''
    owner = (f'<p>Ответственный за сервис: {escape(operator)}.</p>' if operator else
             '<p>Сведения об ответственном за сервис пока не опубликованы. Уточнить их можно у организатора, который предоставил вам доступ.</p>')
    support = (f'<p>Поддержка: <a href="mailto:{quote(contact, safe="@.+-")}">{escape(contact)}</a>.</p>' if contact else
               '<p>Публичный контакт поддержки ещё не указан. По вопросам доступа обратитесь к организатору M-Flow.</p>')
    return f'''<h1>Данные и помощь</h1><p>Здесь описано, какие сведения использует M-Flow и кому они доступны. Информация об ответственном и порядке обработки должна быть дополнена организатором до использования с реальными учениками.</p>
        <section class="card"><h2>Что хранится</h2><p>Логин и роль аккаунта, защищённый хеш пароля и технические записи входа. Если вы добавили почту для восстановления, сохраняются подтверждённый адрес и данные его подтверждения. Пароли и действующие ссылки восстановления нельзя публиковать.</p>
        <p>Также сохраняются проекты, задачи, отчёты, материалы по ссылкам, история отправок и решений, оценки и участие в учебных группах. Учебный профиль может содержать класс, навыки и описание, которые пользователь заполнил сам.</p></section>
        <section class="card"><h2>Кто видит сведения</h2><p>Проекты доступны их участникам согласно роли. Руководитель подключается по согласованию; вступление в учебную группу само по себе не открывает проект. Личные оценки доступны по действующим правилам проекта, а не всему классу.</p>
        <p>Профиль навыков появляется в каталоге только после включения показа пользователем. Скрытие каталога не удаляет прошлые работы и членство в проектах.</p></section>
        <section class="card"><h2>Почта и материалы</h2><p>Почта используется для подтверждения адреса и восстановления доступа. Служебные письма отправляются через почтового провайдера, выбранного организатором. Рекламной рассылки в приложении нет.</p>
        <p>Видео и презентации открываются на внешних сайтах по вашим ссылкам; права на эти материалы задаются там. Настройки темы сохраняются в браузере, вход использует защищённую cookie сессии.</p></section>
        <section class="card"><h2>Вопросы, исправление и удаление данных</h2>{owner}{support}<p>Удаление аккаунта и связанных учебных записей сейчас не выполняется пользователем автоматически. Порядок обращения, сроки хранения и реквизиты ответственного должен определить организатор. Эта страница не заменяет заполненную политику конфиденциальности и не означает получение согласия.</p></section>'''
